#!/usr/bin/env node

import {createHash} from "node:crypto";
import {lstat, readFile, unlink, writeFile} from "node:fs/promises";
import path from "node:path";
import {fileURLToPath, pathToFileURL} from "node:url";

const SCRIPT_PATH = fileURLToPath(import.meta.url);
const PROJECT_ROOT = path.resolve(path.dirname(SCRIPT_PATH), "..");
const PRODUCTION_RENDERER_ROOT = path.join(
  PROJECT_ROOT,
  "apps/web/public/flash-assets/courses",
);
const GENERATED_HEADER =
  "/* Generated by scripts/build-safe-ffdec-canvas-adapter.mjs. */";
const METADATA_START = "var METADATA = deepFreeze(";
const METADATA_END = ");\nvar readyPromise";
const RENDER_START = "function render(targetCanvas, request) {";
const RENDER_END = '\n\nvar registry = global["HELP_MATH_CANVAS_ASSETS"];';
const SHA256_PATTERN = /^[a-f0-9]{64}$/;
const ANIMATION_ID_PATTERN = /^course-[a-z0-9-]+$/;

export const ADAPTIVE_PROFILE = Object.freeze({
  schemaVersion: 1,
  mode: "adaptive-integer",
  supportedRenderScales: Object.freeze([1, 2]),
  bitmapPolicy: "source-evidence-only",
});

export class AdaptiveCanvasError extends Error {
  constructor(message, {code = "ADAPTIVE_CANVAS_GENERATION_FAILED", lane = null} = {}) {
    super(message);
    this.name = "AdaptiveCanvasError";
    this.code = code;
    if (lane !== null) this.lane = lane;
  }
}

function invariant(condition, message, options) {
  if (!condition) throw new AdaptiveCanvasError(message, options);
}

function specialLane(message) {
  throw new AdaptiveCanvasError(
    `${message}; route this renderer to the special lane`,
    {code: "SPECIAL_LANE_REQUIRED", lane: "special"},
  );
}

export function sha256(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function countString(source, marker) {
  return source.split(marker).length - 1;
}

function countPattern(source, pattern) {
  return source.match(pattern)?.length ?? 0;
}

function replaceExactlyOnce(source, marker, replacement, label) {
  const observed = countString(source, marker);
  invariant(
    observed === 1,
    `${label}: expected exactly one marker, observed ${observed}`,
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  return source.replace(marker, replacement);
}

function parseMetadata(source) {
  invariant(
    countString(source, METADATA_START) === 1,
    "metadata: expected exactly one METADATA declaration",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  const start = source.indexOf(METADATA_START) + METADATA_START.length;
  const end = source.indexOf(METADATA_END, start);
  invariant(
    end >= 0 && source.indexOf(METADATA_END, end + METADATA_END.length) < 0,
    "metadata: expected exactly one supported METADATA terminator",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  const text = source.slice(start, end);
  let value;
  try {
    value = JSON.parse(text);
  } catch (error) {
    throw new AdaptiveCanvasError(
      `metadata: expected a JSON object (${error.message})`,
      {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
    );
  }
  invariant(
    value && typeof value === "object" && !Array.isArray(value),
    "metadata: expected an object",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  return {start, end, text, value};
}

function extractRenderSection(source) {
  invariant(
    countString(source, RENDER_START) === 1,
    "renderer: expected exactly one direct render(targetCanvas, request) function",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  const start = source.indexOf(RENDER_START);
  const end = source.indexOf(RENDER_END, start);
  invariant(
    end >= 0,
    "renderer: supported render function must be followed directly by the registry",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  return {start, end, text: source.slice(start, end)};
}

function analyzeTransforms(source, renderText) {
  return Object.freeze({
    standaloneContextSetTransformCalls: countPattern(
      source,
      /(?<![.\w])ctx\.setTransform\s*\(/g,
    ),
    offscreenContextSetTransformCalls: countPattern(
      source,
      /\bo\.ctx\.setTransform\s*\(/g,
    ),
    directResetTransformCalls:
      countPattern(source, /(?<![.\w])ctx\.resetTransform\s*\(/g) +
      countPattern(source, /\bo\.ctx\.resetTransform\s*\(/g),
    clipCalls: countPattern(source, /(?<![.\w])ctx\.clip\s*\(/g),
    globalCompositeOperationReferences: countPattern(
      source,
      /\.globalCompositeOperation\b/g,
    ),
    sourceStrokeResetSites: countPattern(
      source,
      /draw(?:Morph)?Path\s*\(\s*ctx[^\n;]*,\s*true(?:\s*,|\s*\))/g,
    ),
    scalingGridAssignments: countPattern(
      source,
      /\bscalingGrids\s*\[[^\]\r\n]+\]\s*=/g,
    ),
    rootFrameImageTableReferences: countPattern(source, /\bROOT_FRAME_IMAGES\b/g),
    authoredRootIdentityTransforms: countString(
      renderText,
      "    ctx.setTransform(1, 0, 0, 1, 0, 0);",
    ),
    authoredRootAdaptiveTransforms: countString(
      renderText,
      "    ctx.setTransform(k, 0, 0, k, 0, 0);",
    ),
    renderContextSetTransformCalls: countPattern(
      renderText,
      /(?<![.\w])ctx\.setTransform\s*\(/g,
    ),
    embeddedBitmapDataUriCount: countString(source, "data:image/"),
  });
}

function rejectSpecialLaneHazards(counts) {
  if (
    counts.offscreenContextSetTransformCalls > 0 ||
    counts.directResetTransformCalls > 0 ||
    counts.sourceStrokeResetSites > 0 ||
    counts.scalingGridAssignments > 0 ||
    counts.rootFrameImageTableReferences > 0 ||
    counts.standaloneContextSetTransformCalls > 3 ||
    counts.clipCalls > 9 ||
    counts.globalCompositeOperationReferences > 12
  ) {
    specialLane(
      "renderer: multi-reset, stroke-reset, root-bitmap, mask, or offscreen-composite structure is not mechanically scalable",
    );
  }
}

function validateSupportedStructure(source, renderText, counts) {
  invariant(
    countString(source, GENERATED_HEADER) === 1,
    "renderer: input is not the supported safe FFDec adapter family",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  invariant(
    countString(source, "var scalingGrids = {};") === 1,
    "renderer: scaling-grid declaration is not the supported empty form",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  rejectSpecialLaneHazards(counts);

  const isMinimalSupportedProfile =
    counts.standaloneContextSetTransformCalls === 1 &&
    counts.clipCalls === 0 &&
    counts.globalCompositeOperationReferences === 0;
  const isSafeFfdecStaticProfile =
    counts.standaloneContextSetTransformCalls === 3 &&
    counts.clipCalls === 9 &&
    counts.globalCompositeOperationReferences === 12 &&
    countString(source, "function drawMorphPath(ctx, p, ratio, doStroke, scaleMode) {") === 1 &&
    countString(source, "function drawPath(ctx, p, doStroke, scaleMode) {") === 1;
  invariant(
    isMinimalSupportedProfile || isSafeFfdecStaticProfile,
    "renderer: transform/mask boilerplate does not match a supported adaptive-v1 profile",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  invariant(
    counts.renderContextSetTransformCalls === 1 &&
      counts.authoredRootIdentityTransforms === 1 &&
      counts.authoredRootAdaptiveTransforms === 0,
    "renderer: expected one unique authored root identity transform",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  invariant(
    countString(renderText, "request.renderScale") === 0,
    "renderer: input is already adaptive or contains an ambiguous renderScale contract",
    {code: "ALREADY_ADAPTIVE_OR_AMBIGUOUS"},
  );
  return isMinimalSupportedProfile
    ? "safe-ffdec-minimal-single-root-v1"
    : "safe-ffdec-static-no-source-reset-v1";
}

function resolutionMetadata(width, height) {
  return {
    schemaVersion: ADAPTIVE_PROFILE.schemaVersion,
    mode: ADAPTIVE_PROFILE.mode,
    nativeWidth: width,
    nativeHeight: height,
    supportedRenderScales: [...ADAPTIVE_PROFILE.supportedRenderScales],
  };
}

function insertResolutionMetadata(source, parsedMetadata, width, height) {
  const trailingWhitespace = parsedMetadata.text.match(/\s*$/)?.[0] ?? "";
  const jsonBody = parsedMetadata.text.slice(
    0,
    parsedMetadata.text.length - trailingWhitespace.length,
  );
  invariant(
    jsonBody.endsWith("}"),
    "metadata: object terminator is not in the supported form",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  const valueLines = JSON.stringify(resolutionMetadata(width, height), null, 2).split("\n");
  const property = [
    `  \"resolution\": ${valueLines[0]}`,
    ...valueLines.slice(1).map((line) => `  ${line}`),
  ].join("\n");
  const membersWithWhitespace = jsonBody.slice(0, -1);
  const preCloseWhitespace = membersWithWhitespace.match(/\s*$/)?.[0] ?? "";
  const members = membersWithWhitespace.slice(
    0,
    membersWithWhitespace.length - preCloseWhitespace.length,
  );
  const replacement = `${members},${preCloseWhitespace}${property}\n}${trailingWhitespace}`;
  return {
    source: `${source.slice(0, parsedMetadata.start)}${replacement}${source.slice(parsedMetadata.end)}`,
    original: parsedMetadata.text,
    replacement,
  };
}

function originalBackingGuard(width, height) {
  return [
    `    if (targetCanvas.width !== ${width} || targetCanvas.height !== ${height}) {`,
    `        throw new Error(\"targetCanvas must be exactly ${width}x${height}\");`,
    "    }",
  ].join("\n");
}

function adaptiveBackingGuard(width, height) {
  return [
    "    request = request || {};",
    "    var k = request.renderScale;",
    "    if (k !== 1 && k !== 2) {",
    '        throw new Error("renderScale must be exactly 1 or 2");',
    "    }",
    `    if (targetCanvas.width !== ${width} * k || targetCanvas.height !== ${height} * k) {`,
    `        throw new Error(\"targetCanvas must be exactly \" + (${width} * k) + \"x\" + (${height} * k) + \" for renderScale \" + k);`,
    "    }",
  ].join("\n");
}

function validateOptions(options) {
  invariant(
    options && typeof options === "object",
    "generation options are required",
    {code: "INVALID_OPTIONS"},
  );
  invariant(
    Buffer.isBuffer(options.inputBytes),
    "inputBytes must be a Buffer",
    {code: "INVALID_OPTIONS"},
  );
  invariant(
    SHA256_PATTERN.test(options.expectedInputSha256 ?? ""),
    "expectedInputSha256 must be a lowercase SHA-256",
    {code: "INVALID_OPTIONS"},
  );
  invariant(
    ANIMATION_ID_PATTERN.test(options.animationId ?? ""),
    "animationId must be a course animation ID",
    {code: "INVALID_OPTIONS"},
  );
  for (const [label, value] of [
    ["stageWidth", options.stageWidth],
    ["stageHeight", options.stageHeight],
  ]) {
    invariant(
      Number.isSafeInteger(value) && value > 0,
      `${label} must be a positive safe integer`,
      {code: "INVALID_OPTIONS"},
    );
  }
}

export function planAdaptiveCanvas(options) {
  validateOptions(options);
  const inputSha256 = sha256(options.inputBytes);
  invariant(
    inputSha256 === options.expectedInputSha256,
    `input SHA-256 mismatch: expected ${options.expectedInputSha256}, observed ${inputSha256}`,
    {code: "INPUT_SHA256_MISMATCH"},
  );
  const source = options.inputBytes.toString("utf8");
  invariant(
    Buffer.from(source, "utf8").equals(options.inputBytes),
    "input renderer is not lossless UTF-8 text",
    {code: "INPUT_ENCODING_MISMATCH"},
  );

  const metadata = parseMetadata(source);
  invariant(
    metadata.value.schemaVersion === 1,
    `metadata schemaVersion mismatch: expected 1, observed ${metadata.value.schemaVersion}`,
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );
  invariant(
    metadata.value.animationId === options.animationId,
    `metadata animationId mismatch: expected ${options.animationId}, observed ${metadata.value.animationId}`,
    {code: "ANIMATION_ID_MISMATCH"},
  );
  invariant(
    metadata.value.stage?.width === options.stageWidth &&
      metadata.value.stage?.height === options.stageHeight,
    `metadata native stage mismatch: expected ${options.stageWidth}x${options.stageHeight}`,
    {code: "NATIVE_STAGE_MISMATCH"},
  );
  invariant(
    metadata.value.resolution === undefined,
    "metadata already contains a resolution contract",
    {code: "ALREADY_ADAPTIVE_OR_AMBIGUOUS"},
  );
  rejectSpecialLaneHazards(analyzeTransforms(source, ""));
  const inputRender = extractRenderSection(source);
  const inputTransformCounts = analyzeTransforms(source, inputRender.text);
  const supportedProfile = validateSupportedStructure(
    source,
    inputRender.text,
    inputTransformCounts,
  );
  const registryAssignment =
    `registry[\"${options.animationId}\"] = Object.freeze({metadata: METADATA, ready: ready, resolveFrameState: resolveFrameState, render: render});`;
  invariant(
    countString(source, registryAssignment) === 1,
    "renderer registry assignment does not match the expected animationId and direct render contract",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );

  const originalGuard = originalBackingGuard(options.stageWidth, options.stageHeight);
  invariant(
    countString(inputRender.text, originalGuard) === 1,
    "renderer: native backing-store guard is not the supported exact form",
    {code: "UNSUPPORTED_RENDERER_STRUCTURE", lane: "special"},
  );

  const metadataEdit = insertResolutionMetadata(
    source,
    metadata,
    options.stageWidth,
    options.stageHeight,
  );
  const renderAfterMetadata = extractRenderSection(metadataEdit.source);
  const adaptiveGuard = adaptiveBackingGuard(options.stageWidth, options.stageHeight);
  let adaptiveRenderText = replaceExactlyOnce(
    renderAfterMetadata.text,
    originalGuard,
    adaptiveGuard,
    "renderer backing-store guard",
  );
  adaptiveRenderText = replaceExactlyOnce(
    adaptiveRenderText,
    "    ctx.setTransform(1, 0, 0, 1, 0, 0);",
    "    ctx.setTransform(k, 0, 0, k, 0, 0);",
    "authored root transform",
  );
  const outputSource = `${metadataEdit.source.slice(0, renderAfterMetadata.start)}${adaptiveRenderText}${metadataEdit.source.slice(renderAfterMetadata.end)}`;

  const outputMetadata = parseMetadata(outputSource);
  invariant(
    JSON.stringify(outputMetadata.value.resolution) ===
      JSON.stringify(resolutionMetadata(options.stageWidth, options.stageHeight)),
    "generated resolution metadata failed its exact self-check",
    {code: "OUTPUT_SELF_CHECK_FAILED"},
  );
  const outputRender = extractRenderSection(outputSource);
  const outputTransformCounts = analyzeTransforms(outputSource, outputRender.text);
  invariant(
    outputTransformCounts.renderContextSetTransformCalls === 1 &&
      outputTransformCounts.authoredRootIdentityTransforms === 0 &&
      outputTransformCounts.authoredRootAdaptiveTransforms === 1,
    "generated authored root transform failed its exact self-check",
    {code: "OUTPUT_SELF_CHECK_FAILED"},
  );
  invariant(
    countString(outputRender.text, adaptiveGuard) === 1 &&
      countString(outputRender.text, "request.renderScale") === 1,
    "generated renderScale guard failed its exact self-check",
    {code: "OUTPUT_SELF_CHECK_FAILED"},
  );
  invariant(
    outputTransformCounts.embeddedBitmapDataUriCount ===
      inputTransformCounts.embeddedBitmapDataUriCount,
    "embedded bitmap payload count changed",
    {code: "OUTPUT_SELF_CHECK_FAILED"},
  );

  let reverted = replaceExactlyOnce(
    outputSource,
    metadataEdit.replacement,
    metadataEdit.original,
    "resolution metadata reversion",
  );
  reverted = replaceExactlyOnce(
    reverted,
    adaptiveGuard,
    originalGuard,
    "adaptive backing-store guard reversion",
  );
  reverted = replaceExactlyOnce(
    reverted,
    "    ctx.setTransform(k, 0, 0, k, 0, 0);",
    "    ctx.setTransform(1, 0, 0, 1, 0, 0);",
    "adaptive root transform reversion",
  );
  invariant(
    reverted === source,
    "bounded-diff proof failed: output includes a change outside the three authorized edits",
    {code: "OUTPUT_SELF_CHECK_FAILED"},
  );

  const outputBytes = Buffer.from(outputSource, "utf8");
  const receipt = {
    schemaVersion: 1,
    lane: "adaptive-v1",
    routing: "mechanical-single-authored-root",
    status: "generated-candidate-not-integrated",
    input: {
      path: options.inputPath ?? null,
      bytes: options.inputBytes.length,
      sha256: inputSha256,
      expectedSha256: options.expectedInputSha256,
      animationId: options.animationId,
      nativeStage: {width: options.stageWidth, height: options.stageHeight},
    },
    output: {
      path: options.outputPath ?? null,
      bytes: outputBytes.length,
      sha256: sha256(outputBytes),
    },
    resolution: resolutionMetadata(options.stageWidth, options.stageHeight),
    structure: {
      supportedProfile,
      inputTransformCounts,
      outputTransformCounts,
      authorizedEditCounts: {
        resolutionMetadata: 1,
        renderScaleReadAndGuard: 1,
        exactBackingStoreGuard: 1,
        authoredRootTransform: 1,
      },
      reverseProof: "byte-identical-input-after-reverting-three-authorized-edits",
    },
    boundaries: {
      singleRendererOnly: true,
      productionIntegration: false,
      bitmapPolicy: ADAPTIVE_PROFILE.bitmapPolicy,
      fidelityAcceptance: false,
      audioAcceptance: false,
      humanAcceptance: false,
      ownerAcceptance: false,
      strictCompletion: false,
      releaseOrPublication: false,
    },
  };
  return {outputBytes, receipt};
}

function pathIsWithin(candidate, root) {
  const relative = path.relative(root, candidate);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

async function requireRegularFile(filePath, label) {
  const stats = await lstat(filePath);
  invariant(stats.isFile(), `${label} must be a regular file`, {code: "INVALID_PATH"});
}

async function requireAbsent(filePath, label) {
  try {
    await lstat(filePath);
  } catch (error) {
    if (error?.code === "ENOENT") return;
    throw error;
  }
  throw new AdaptiveCanvasError(`${label} already exists; refusing to overwrite`, {
    code: "OUTPUT_ALREADY_EXISTS",
  });
}

export async function generateAdaptiveCanvasFile(options) {
  const inputPath = path.resolve(options.inputPath ?? "");
  const outputPath = path.resolve(options.outputPath ?? "");
  const receiptPath = path.resolve(options.receiptPath ?? "");
  invariant(options.inputPath, "inputPath is required", {code: "INVALID_OPTIONS"});
  invariant(options.outputPath, "outputPath is required", {code: "INVALID_OPTIONS"});
  invariant(options.receiptPath, "receiptPath is required", {code: "INVALID_OPTIONS"});
  invariant(
    inputPath !== outputPath && inputPath !== receiptPath && outputPath !== receiptPath,
    "input, output, and receipt paths must be distinct",
    {code: "INVALID_PATH"},
  );
  invariant(
    !pathIsWithin(outputPath, PRODUCTION_RENDERER_ROOT) &&
      !pathIsWithin(receiptPath, PRODUCTION_RENDERER_ROOT),
    "prototype output and receipt must stay outside generated production renderer paths",
    {code: "PRODUCTION_OUTPUT_BLOCKED"},
  );
  await requireRegularFile(inputPath, "inputPath");
  await Promise.all([
    requireAbsent(outputPath, "outputPath"),
    requireAbsent(receiptPath, "receiptPath"),
  ]);
  const inputBytes = await readFile(inputPath);
  const planned = planAdaptiveCanvas({
    ...options,
    inputBytes,
    inputPath,
    outputPath,
  });
  const receiptBytes = Buffer.from(`${JSON.stringify(planned.receipt, null, 2)}\n`, "utf8");
  await writeFile(outputPath, planned.outputBytes, {flag: "wx"});
  try {
    await writeFile(receiptPath, receiptBytes, {flag: "wx"});
  } catch (error) {
    await unlink(outputPath).catch(() => {});
    throw error;
  }
  return planned.receipt;
}

function parseCli(argv) {
  const aliases = new Map([
    ["--input", "inputPath"],
    ["--output", "outputPath"],
    ["--receipt", "receiptPath"],
    ["--expected-input-sha256", "expectedInputSha256"],
    ["--animation-id", "animationId"],
    ["--stage-width", "stageWidth"],
    ["--stage-height", "stageHeight"],
  ]);
  const parsed = {};
  for (let index = 0; index < argv.length; index += 2) {
    const flag = argv[index];
    const key = aliases.get(flag);
    invariant(key, `unknown CLI flag: ${flag}`, {code: "INVALID_OPTIONS"});
    invariant(
      parsed[key] === undefined,
      `duplicate CLI flag: ${flag}`,
      {code: "INVALID_OPTIONS"},
    );
    const value = argv[index + 1];
    invariant(
      typeof value === "string" && !value.startsWith("--"),
      `missing value for CLI flag: ${flag}`,
      {code: "INVALID_OPTIONS"},
    );
    parsed[key] = key === "stageWidth" || key === "stageHeight" ? Number(value) : value;
  }
  return parsed;
}

async function main() {
  const receipt = await generateAdaptiveCanvasFile(parseCli(process.argv.slice(2)));
  process.stdout.write(`${JSON.stringify(receipt, null, 2)}\n`);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  main().catch((error) => {
    const code = error?.code ? ` ${error.code}` : "";
    process.stderr.write(`${error?.name ?? "Error"}${code}: ${error?.message ?? error}\n`);
    process.exitCode = 1;
  });
}
